const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const volcano = ee.Geometry.Point([160.642, 56.056]); // Klyuchevskaya Sopka
  const date = '2025-08-08';
  const bufferRadius = 100000; // 100km buffer for analysis

  // 2. Create directional sectors (East and West)
  const volcanoBuffer = volcano.buffer(bufferRadius);

  // Create East sector (45° to 135° from North)
  const eastSector = volcano.buffer(bufferRadius).intersection(
    volcano.buffer(bufferRadius * 2).bounds()
      .rotate(90, volcano)
  );

  // Create West sector (225° to 315° from North)
  const westSector = volcano.buffer(bufferRadius).intersection(
    volcano.buffer(bufferRadius * 2).bounds()
      .rotate(270, volcano)
  );

  // 3. Try Sentinel-2 first (best resolution)
  let s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(volcano)
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  // Check if collection is empty
  const s2Count = s2.size().getInfo();
  console.log(`Sentinel-2 images on ${date}: ${s2Count}`);

  let ashImg;
  let collectionUsed = 'Sentinel-2';

  if (s2Count === 0) {
    // Try MODIS as fallback (daily coverage)
    console.log('Trying MODIS as fallback...');
    const modis = ee.ImageCollection('MODIS/006/MOD09GA')
      .filterBounds(volcano)
      .filterDate(date, ee.Date(date).advance(1, 'day'));

    const modisCount = modis.size().getInfo();
    console.log(`MODIS images on ${date}: ${modisCount}`);

    if (modisCount === 0) {
      console.log('<answer>C1</answer>');
      return;
    }

    ashImg = modis.first();
    collectionUsed = 'MODIS';

    // For MODIS, use band combination for ash detection
    // Bands: surf_refl_b07 (2.1μm), surf_refl_b06 (1.6μm), surf_refl_b01 (0.65μm)
    // Ash appears bright in SWIR (b07) and dark in visible (b01)
    ashImg = ashImg.select(['surf_refl_b07', 'surf_refl_b02', 'surf_refl_b01']);
  } else {
    ashImg = s2.first();
    // For Sentinel-2, use SWIR bands for ash detection
    // Bands: B12 (2.19μm), B8A (0.865μm), B4 (0.665μm)
    ashImg = ashImg.select(['B12', 'B8A', 'B4']);
  }

  console.log(`Using ${collectionUsed} image`);

  // 4. Create ash detection mask
  // Ash typically has high reflectance in SWIR and low in visible
  let ashMask;
  if (collectionUsed === 'Sentinel-2') {
    const swir = ashImg.select('B12');
    const red = ashImg.select('B4');
    // Simple ash index: SWIR - Red (ash is bright in SWIR, dark in red)
    const ashIndex = swir.subtract(red).divide(swir.add(red).add(0.0001));
    ashMask = ashIndex.gt(0.1); // Threshold for ash detection
  } else { // MODIS
    const swir = ashImg.select('surf_refl_b07');
    const red = ashImg.select('surf_refl_b01');
    const ashIndex = swir.subtract(red).divide(swir.add(red).add(0.0001));
    ashMask = ashIndex.gt(0.1);
  }

  // 5. Count pixels in East and West sectors
  const eastCount = ashMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: eastSector,
    scale: 1000,
    maxPixels: 1e9
  }).getNumber('constant').getInfo();

  const westCount = ashMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: westSector,
    scale: 1000,
    maxPixels: 1e9
  }).getNumber('constant').getInfo();

  console.log(`East sector ash pixels: ${eastCount}`);
  console.log(`West sector ash pixels: ${westCount}`);
  console.log(`Total ash pixels: ${eastCount + westCount}`);

  // 6. Validate results
  if (eastCount === null || westCount === null) {
    console.log('<answer>C3</answer>');
    return;
  }

  const totalAsh = eastCount + westCount;
  if (totalAsh === 0) {
    console.log('No ash plume detected');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Determine direction
  const eastRatio = eastCount / totalAsh;
  const isPrimarilyEast = eastRatio > 0.6; // >60% in east

  console.log(`East proportion: ${(eastRatio * 100).toFixed(1)}%`);

  if (isPrimarilyEast) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(console.error);
